namespace sv_b1927f0c14aa408bae067fbe291cbd07.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_b1927f0c14aa408bae067fbe291cbd07.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">&#128100;</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">&#128276;</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">&#128274;</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">&#127912;</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(toastMessage))
            {
                <div class="toast @toastType">@toastMessage</div>
            }

            @switch (activeSection)
            {
                case "Profile":
                    <section class="settings-section">
                        <h2>Profile Settings</h2>
                        <div class="profile-form">
                            <div class="avatar-preview">
                                <img src="@editProfile.AvatarUrl" alt="Avatar" class="avatar-image" />
                                <span class="avatar-url">@editProfile.AvatarUrl</span>
                            </div>
                            <div class="form-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="editProfile.DisplayName" />
                            </div>
                            <div class="form-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="editProfile.Email" />
                            </div>
                            <div class="form-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
                            </div>
                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </section>
                    break;

                case "Notifications":
                    <section class="settings-section">
                        <h2>Notification Preferences</h2>
                        <div class="notification-form">
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Email Notifications</span>
                                    <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Push Notifications</span>
                                    <input type="checkbox" @bind="editNotifications.PushNotifications" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Weekly Digest</span>
                                    <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>

                            <h3>Muted Channels</h3>
                            <div class="channel-list">
                                @foreach (var channel in availableChannels)
                                {
                                    <label class="channel-item">
                                        <input type="checkbox"
                                               checked="@editNotifications.MutedChannels.Contains(channel)"
                                               @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                        <span>@channel</span>
                                    </label>
                                }
                            </div>
                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                            </div>
                        </div>
                    </section>
                    break;

                case "Security":
                    <section class="settings-section">
                        <h2>Security Settings</h2>

                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                            </button>
                            @if (showPasswordPanel)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(passwordError))
                                    {
                                        <div class="error-message">@passwordError</div>
                                    }
                                    <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group security-toggle">
                            <label class="toggle-label">
                                <span>Two-Factor Authentication</span>
                                <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                                    @(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                                </span>
                            </label>
                        </div>

                        @if (securitySettings?.LastPasswordChange != null)
                        {
                            <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-container">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @if (securitySettings?.Sessions != null)
                                    {
                                        @foreach (var session in securitySettings.Sessions)
                                        {
                                            <tr>
                                                <td>@session.Device</td>
                                                <td>@session.Location</td>
                                                <td>@session.LastActive.ToString("g")</td>
                                                <td>
                                                    @if (session != securitySettings.Sessions.FirstOrDefault())
                                                    {
                                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                    }
                                                    else
                                                    {
                                                        <span class="current-session-badge">Current</span>
                                                    }
                                                </td>
                                            </tr>
                                        }
                                    }
                                </tbody>
                            </table>
                        </div>

                        @if (showRevokeConfirmation)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal-dialog" @onclick:stopPropagation="true">
                                    <h3>Confirm Session Revocation</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                    <div class="modal-actions">
                                        <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </section>
                    break;

                case "Appearance":
                    <section class="settings-section">
                        <h2>Appearance Settings</h2>
                        <div class="appearance-form">
                            <div class="form-group">
                                <label>Theme</label>
                                <div class="radio-group">
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="Light"
                                               checked="@(editAppearance.Theme == "Light")"
                                               @onchange='() => editAppearance.Theme = "Light"' />
                                        <span>Light</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="Dark"
                                               checked="@(editAppearance.Theme == "Dark")"
                                               @onchange='() => editAppearance.Theme = "Dark"' />
                                        <span>Dark</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="System"
                                               checked="@(editAppearance.Theme == "System")"
                                               @onchange='() => editAppearance.Theme = "System"' />
                                        <span>System</span>
                                    </label>
                                </div>
                            </div>

                            <div class="form-group">
                                <label>Font Size</label>
                                <div class="radio-group">
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Small"
                                               checked="@(editAppearance.FontSize == "Small")"
                                               @onchange='() => editAppearance.FontSize = "Small"' />
                                        <span>Small</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Medium"
                                               checked="@(editAppearance.FontSize == "Medium")"
                                               @onchange='() => editAppearance.FontSize = "Medium"' />
                                        <span>Medium</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Large"
                                               checked="@(editAppearance.FontSize == "Large")"
                                               @onchange='() => editAppearance.FontSize = "Large"' />
                                        <span>Large</span>
                                    </label>
                                </div>
                            </div>

                            <div class="form-group">
                                <label for="language">Language</label>
                                <select id="language" @bind="editAppearance.Language">
                                    <option value="en">English</option>
                                    <option value="es">Español</option>
                                    <option value="fr">Français</option>
                                    <option value="de">Deutsch</option>
                                    <option value="ja">日本語</option>
                                    <option value="zh">中文</option>
                                </select>
                            </div>

                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Compact Mode</span>
                                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>

                            <div class="live-preview @GetPreviewClasses()">
                                <h4>Live Preview</h4>
                                <p class="preview-text">This is how your content will look with the selected settings.</p>
                                <div class="preview-card">
                                    <span class="preview-title">Sample Card</span>
                                    <span class="preview-body">Preview content with your chosen appearance.</span>
                                </div>
                            </div>

                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                            </div>
                        </div>
                    </section>
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string toastMessage = "";
    private string toastType = "";

    // Profile
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        toastMessage = "";
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    editProfile = EditableProfile.FromRecord(savedProfile);
                    break;
                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    editNotifications = EditableNotifications.FromRecord(prefs);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    break;
                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    editAppearance = EditableAppearance.FromRecord(appearance);
                    break;
            }
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = editProfile.ToRecord();
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            editProfile = EditableProfile.FromRecord(savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = editNotifications.ToRecord();
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        passwordError = "";
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        CancelRevoke();
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = editAppearance.ToRecord();
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    // Editable view models
    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static EditableProfile FromRecord(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };

        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();

        public static EditableNotifications FromRecord(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };

        public NotificationPrefs ToRecord() => new(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "en";
        public bool CompactMode { get; set; }

        public static EditableAppearance FromRecord(AppearanceSettings a) => new()
        {
            Theme = a.Theme,
            FontSize = a.FontSize,
            Language = a.Language,
            CompactMode = a.CompactMode
        };

        public AppearanceSettings ToRecord() => new(Theme, FontSize, Language, CompactMode);
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: #555;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

/* Toast */
.toast {
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    font-size: 0.9rem;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.toast.info {
    background: #d1ecf1;
    color: #0c5460;
    border: 1px solid #bee5eb;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Form styles */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.15s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Buttons */
.btn-primary {
    background: #0d6efd;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-secondary:hover {
    background: #5a6268;
}

.btn-danger {
    background: #dc3545;
    color: white;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

.btn-danger:hover {
    background: #c82333;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    background: #dee2e6;
}

.avatar-url {
    font-size: 0.8rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggle switches */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 0;
    cursor: pointer;
    font-size: 0.95rem;
}

.toggle-label input[type="checkbox"] {
    width: 40px;
    height: 20px;
    appearance: none;
    background: #ccc;
    border-radius: 10px;
    position: relative;
    cursor: pointer;
    transition: background 0.2s;
}

.toggle-label input[type="checkbox"]::after {
    content: '';
    position: absolute;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: white;
    top: 2px;
    left: 2px;
    transition: transform 0.2s;
}

.toggle-label input[type="checkbox"]:checked {
    background: #0d6efd;
}

.toggle-label input[type="checkbox"]:checked::after {
    transform: translateX(20px);
}

/* Channels */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
    font-size: 0.9rem;
}

.channel-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #0d6efd;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 0.8rem;
    color: #666;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* Security */
.security-toggle {
    padding: 1rem 0;
    border-bottom: 1px solid #eee;
}

.status-indicator {
    font-size: 0.8rem;
    padding: 0.25rem 0.75rem;
    border-radius: 12px;
    font-weight: 500;
}

.status-enabled {
    background: #d4edda;
    color: #155724;
}

.status-disabled {
    background: #f8d7da;
    color: #721c24;
}

.info-text {
    font-size: 0.85rem;
    color: #6c757d;
    margin: 0.5rem 0;
}

.current-session-badge {
    font-size: 0.75rem;
    background: #e7f1ff;
    color: #0d6efd;
    padding: 0.2rem 0.6rem;
    border-radius: 10px;
    font-weight: 500;
}

/* Sessions table */
.sessions-table-container {
    overflow-x: auto;
}

.sessions-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9rem;
}

.sessions-table th {
    text-align: left;
    padding: 0.75rem;
    background: #f8f9fa;
    border-bottom: 2px solid #dee2e6;
    font-weight: 600;
    color: #555;
}

.sessions-table td {
    padding: 0.75rem;
    border-bottom: 1px solid #eee;
}

.sessions-table tr:hover {
    background: #f8f9fa;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-dialog h3 {
    margin-top: 0;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-label input[type="radio"] {
    accent-color: #0d6efd;
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.preview-card {
    padding: 1rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    margin-top: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.preview-title {
    font-weight: 600;
}

.preview-body {
    font-size: 0.9em;
    color: #666;
}

/* Preview theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #2a2a3e;
}

.preview-theme-dark .preview-body {
    color: #aaa;
}

.preview-theme-system {
    background: #f0f4f8;
    color: #333;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    gap: 0.25rem;
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #6c757d;
    font-size: 1rem;
}

/* Error message */
.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

namespace sv_b1927f0c14aa408bae067fbe291cbd07.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_b1927f0c14aa408bae067fbe291cbd07.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">&#128100;</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">&#128276;</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">&#128274;</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">&#127912;</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(toastMessage))
            {
                <div class="toast @toastType">@toastMessage</div>
            }

            @switch (activeSection)
            {
                case "Profile":
                    <section class="settings-section">
                        <h2>Profile Settings</h2>
                        <div class="profile-form">
                            <div class="avatar-preview">
                                <img src="@editProfile.AvatarUrl" alt="Avatar" class="avatar-image" />
                                <span class="avatar-url">@editProfile.AvatarUrl</span>
                            </div>
                            <div class="form-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="editProfile.DisplayName" />
                            </div>
                            <div class="form-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="editProfile.Email" />
                            </div>
                            <div class="form-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
                            </div>
                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </section>
                    break;

                case "Notifications":
                    <section class="settings-section">
                        <h2>Notification Preferences</h2>
                        <div class="notification-form">
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Email Notifications</span>
                                    <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Push Notifications</span>
                                    <input type="checkbox" @bind="editNotifications.PushNotifications" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>
                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Weekly Digest</span>
                                    <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>

                            <h3>Muted Channels</h3>
                            <div class="channel-list">
                                @foreach (var channel in availableChannels)
                                {
                                    <label class="channel-item">
                                        <input type="checkbox"
                                               checked="@editNotifications.MutedChannels.Contains(channel)"
                                               @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                        <span>@channel</span>
                                    </label>
                                }
                            </div>
                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                            </div>
                        </div>
                    </section>
                    break;

                case "Security":
                    <section class="settings-section">
                        <h2>Security Settings</h2>

                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(showPasswordPanel ? "▼" : "▶")</span>
                            </button>
                            @if (showPasswordPanel)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                    </div>
                                    @if (!string.IsNullOrEmpty(passwordError))
                                    {
                                        <div class="error-message">@passwordError</div>
                                    }
                                    <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group security-toggle">
                            <label class="toggle-label">
                                <span>Two-Factor Authentication</span>
                                <span class="status-indicator @(securitySettings?.TwoFactorEnabled == true ? "status-enabled" : "status-disabled")">
                                    @(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")
                                </span>
                            </label>
                        </div>

                        @if (securitySettings?.LastPasswordChange != null)
                        {
                            <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-container">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @if (securitySettings?.Sessions != null)
                                    {
                                        @foreach (var session in securitySettings.Sessions)
                                        {
                                            <tr>
                                                <td>@session.Device</td>
                                                <td>@session.Location</td>
                                                <td>@session.LastActive.ToString("g")</td>
                                                <td>
                                                    @if (session != securitySettings.Sessions.FirstOrDefault())
                                                    {
                                                        <button class="btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                    }
                                                    else
                                                    {
                                                        <span class="current-session-badge">Current</span>
                                                    }
                                                </td>
                                            </tr>
                                        }
                                    }
                                </tbody>
                            </table>
                        </div>

                        @if (showRevokeConfirmation)
                        {
                            <div class="modal-overlay" @onclick="CancelRevoke">
                                <div class="modal-dialog" @onclick:stopPropagation="true">
                                    <h3>Confirm Session Revocation</h3>
                                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> from <strong>@sessionToRevoke?.Location</strong>?</p>
                                    <div class="modal-actions">
                                        <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                        <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                    </section>
                    break;

                case "Appearance":
                    <section class="settings-section">
                        <h2>Appearance Settings</h2>
                        <div class="appearance-form">
                            <div class="form-group">
                                <label>Theme</label>
                                <div class="radio-group">
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="Light"
                                               checked="@(editAppearance.Theme == "Light")"
                                               @onchange='() => editAppearance.Theme = "Light"' />
                                        <span>Light</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="Dark"
                                               checked="@(editAppearance.Theme == "Dark")"
                                               @onchange='() => editAppearance.Theme = "Dark"' />
                                        <span>Dark</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="theme" value="System"
                                               checked="@(editAppearance.Theme == "System")"
                                               @onchange='() => editAppearance.Theme = "System"' />
                                        <span>System</span>
                                    </label>
                                </div>
                            </div>

                            <div class="form-group">
                                <label>Font Size</label>
                                <div class="radio-group">
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Small"
                                               checked="@(editAppearance.FontSize == "Small")"
                                               @onchange='() => editAppearance.FontSize = "Small"' />
                                        <span>Small</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Medium"
                                               checked="@(editAppearance.FontSize == "Medium")"
                                               @onchange='() => editAppearance.FontSize = "Medium"' />
                                        <span>Medium</span>
                                    </label>
                                    <label class="radio-label">
                                        <input type="radio" name="fontSize" value="Large"
                                               checked="@(editAppearance.FontSize == "Large")"
                                               @onchange='() => editAppearance.FontSize = "Large"' />
                                        <span>Large</span>
                                    </label>
                                </div>
                            </div>

                            <div class="form-group">
                                <label for="language">Language</label>
                                <select id="language" @bind="editAppearance.Language">
                                    <option value="en">English</option>
                                    <option value="es">Español</option>
                                    <option value="fr">Français</option>
                                    <option value="de">Deutsch</option>
                                    <option value="ja">日本語</option>
                                    <option value="zh">中文</option>
                                </select>
                            </div>

                            <div class="toggle-group">
                                <label class="toggle-label">
                                    <span>Compact Mode</span>
                                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                                    <span class="toggle-switch"></span>
                                </label>
                            </div>

                            <div class="live-preview @GetPreviewClasses()">
                                <h4>Live Preview</h4>
                                <p class="preview-text">This is how your content will look with the selected settings.</p>
                                <div class="preview-card">
                                    <span class="preview-title">Sample Card</span>
                                    <span class="preview-body">Preview content with your chosen appearance.</span>
                                </div>
                            </div>

                            <div class="form-actions">
                                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                            </div>
                        </div>
                    </section>
                    break;
            }
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string toastMessage = "";
    private string toastType = "";

    // Profile
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security
    private SecuritySettings? securitySettings;
    private bool showPasswordPanel;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string passwordError = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionData();
    }

    private async Task SetSection(string section)
    {
        activeSection = section;
        isLoading = true;
        toastMessage = "";
        await LoadSectionData();
    }

    private async Task LoadSectionData()
    {
        try
        {
            switch (activeSection)
            {
                case "Profile":
                    savedProfile = await SettingsService.GetProfileAsync();
                    editProfile = EditableProfile.FromRecord(savedProfile);
                    break;
                case "Notifications":
                    var prefs = await SettingsService.GetNotificationPrefsAsync();
                    editNotifications = EditableNotifications.FromRecord(prefs);
                    break;
                case "Security":
                    securitySettings = await SettingsService.GetSecuritySettingsAsync();
                    break;
                case "Appearance":
                    var appearance = await SettingsService.GetAppearanceAsync();
                    editAppearance = EditableAppearance.FromRecord(appearance);
                    break;
            }
        }
        finally
        {
            isLoading = false;
        }
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = editProfile.ToRecord();
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            editProfile = EditableProfile.FromRecord(savedProfile);
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
            editNotifications.MutedChannels.Add(channel);
        else if (!isMuted)
            editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = editNotifications.ToRecord();
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => showPasswordPanel = !showPasswordPanel;

    private async Task ChangePassword()
    {
        passwordError = "";
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }
        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        showPasswordPanel = false;
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        CancelRevoke();
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

    // Appearance methods
    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{editAppearance.Theme.ToLowerInvariant()} preview-font-{editAppearance.FontSize.ToLowerInvariant()}";
        if (editAppearance.CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = editAppearance.ToRecord();
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved!", "success");
    }

    // Toast
    private void ShowToast(string message, string type)
    {
        toastMessage = message;
        toastType = type;
        _ = DismissToastAfterDelay();
    }

    private async Task DismissToastAfterDelay()
    {
        await Task.Delay(3000);
        toastMessage = "";
        await InvokeAsync(StateHasChanged);
    }

    // Editable view models
    private class EditableProfile
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static EditableProfile FromRecord(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };

        public UserProfile ToRecord() => new(DisplayName, Email, AvatarUrl, Bio);
    }

    private class EditableNotifications
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();

        public static EditableNotifications FromRecord(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };

        public NotificationPrefs ToRecord() => new(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
    }

    private class EditableAppearance
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "en";
        public bool CompactMode { get; set; }

        public static EditableAppearance FromRecord(AppearanceSettings a) => new()
        {
            Theme = a.Theme,
            FontSize = a.FontSize,
            Language = a.Language,
            CompactMode = a.CompactMode
        };

        public AppearanceSettings ToRecord() => new(Theme, FontSize, Language, CompactMode);
    }
}

.settings-dashboard {
    display: flex;
