}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

/* Toast */
.toast {
    padding: 0.75rem 1.25rem;
    border-radius: 6px;
