    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.modal-dialog h3 {
    margin-top: 0;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-label input[type="radio"] {
    accent-color: #0d6efd;
}

/* Live Preview */
.live-preview {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.3s ease;
}

.live-preview h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.preview-card {
    padding: 1rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    margin-top: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.preview-title {
    font-weight: 600;
}

.preview-body {
    font-size: 0.9em;
    color: #666;
}

/* Preview theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #2a2a3e;
}

.preview-theme-dark .preview-body {
    color: #aaa;
}

.preview-theme-system {
    background: #f0f4f8;
    color: #333;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Preview compact */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    gap: 0.25rem;
}

/* Loading */
.loading-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 3rem;
    color: #6c757d;
    font-size: 1rem;
}

/* Error message */
.error-message {
    color: #dc3545;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}
"}

